// The Webhook node wraps the POST body under `body`, while the Form Trigger
// emits its fields flat. Flatten here so everything downstream, starting with
// "OnPage: start crawl", sees the same shape either way.
const incoming = $json && typeof $json === 'object' ? $json : {};
const body = (incoming.body && typeof incoming.body === 'object') ? incoming.body : incoming;

// Reject the call early if a shared secret is configured but not presented.
const EXPECTED_SECRET = '';
if (EXPECTED_SECRET) {
  const headers = incoming.headers || {};
  const supplied = headers['x-trigger-secret'] || headers['X-Trigger-Secret'] || '';
  if (supplied !== EXPECTED_SECRET) {
    throw new Error('Bad or missing x-trigger-secret header.');
  }
}

return [{ json: {
  website_url: String(body.website_url || '').trim(),
  market: String(body.market || 'gb').trim().toLowerCase(),
  language: String(body.language || 'en').trim().toLowerCase(),
  max_crawl_pages: Math.max(1, Math.min(10, Number(body.max_crawl_pages) || 10)),
  brief_doc_id: String(body.brief_doc_id || '').trim()
} }];
